# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- The sheet's late percent: an overdue claim's live due gains it, of its floored due, for every full 30 days overdue.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL;
-- The people a person names as their patrons: others on the same sheet, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id)
);
-- A period can be closed; closing fixes its due-total at that moment (null while it is open).
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
-- The date a person is retired from; null while they are not retired. A claim dated after it is refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- Whether a person is on hold; while held, their open claims count in no live total.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
-- The due a claim had when it was settled (amount times its person's grade's rate, rounded half up
-- to cents), kept so later changes to rates do not alter it. Null for a claim that is not settled,
-- or that was settled while its grade had no rate.
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
-- A claim's status: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID instead.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- The sheet's floor: every live due (not a settled claim's fixed due) is at least it.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL;
-- Claims made by a person on a sheet, listed newest first (by id). The amount is 0.00 or more with
-- two decimals; the date defaults to the sheet's today; the note may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(500)   NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The rate for each grade on a sheet: a percent with two decimals. A grade has at most one rate;
-- a grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    rate     DECIMAL(5, 2) NOT NULL CHECK (rate >= 0),
    CONSTRAINT rate_sheet_grade UNIQUE (sheet_id, grade)
);
-- A sheet: everything else in the app is kept per sheet. A row is created the first time the
-- sheet's id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) NOT NULL PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL
);
-- People on a sheet, listed in the order they were added (by id). The grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a rate with
-- no from-date applies from the beginning of time. A grade has at most one rate per from-date
-- (including at most one without a from-date, which the service ensures).
ALTER TABLE rate DROP CONSTRAINT rate_sheet_grade;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_sheet_grade_from UNIQUE (sheet_id, grade, from_date);
-- A claim gets the sheet's next number when it is opened: 1, 2, ... with no gaps and never reused.
-- The sheet keeps the last number given; voiding a claim clears its number.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN claim_number BIGINT;
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, claim_number);
-- The version of a person, raised each time the person is saved, so an edit made from an
-- out-of-date copy is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- Periods on a sheet: a name unique on the sheet (regardless of case, which the service ensures)
-- and an inclusive from and to date. No two periods on a sheet overlap (the service ensures it).
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CONSTRAINT period_dates CHECK (from_date <= to_date),
    CONSTRAINT period_sheet_name UNIQUE (sheet_id, name)
);
-- The sheet's clerk limit: a clerk can settle a claim only when its due is at or below it. Null
-- means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2);

-- The role given to a user name on a sheet. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    CONSTRAINT sheet_role_user UNIQUE (sheet_id, user_name)
);
-- A person's grade is dated: each grade recorded applies from its from-date, the first one (with no
-- from-date) from the beginning of time. A person has at most one grade per from-date, which the
-- service ensures. The grade each person had becomes their first grade.
CREATE TABLE person_grade (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    from_date DATE,
    grade     CHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, from_date, grade) SELECT id, NULL, grade FROM person;
ALTER TABLE person DROP COLUMN grade;
-- Each sheet has its own "today": every date decision and default date in the sheet uses it, never
-- the real clock. It starts as the real date the sheet was created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- Only a DRAFT claim can be edited; an OPEN claim is changed by voiding it and adding a new one.
-- A voided claim now keeps the number it was given when opened (still never given again).
-- Claims voided before this change had their number cleared, and it cannot be recovered.
SELECT 1;
-- A person's name is unique on its sheet, compared without regard to case. Names are stored with
-- surrounding spaces removed, so the key only needs to fold case.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(100) GENERATED ALWAYS AS (LOWER(name));
ALTER TABLE person ADD CONSTRAINT person_sheet_name UNIQUE (sheet_id, name_key);
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the same
-- person that it corrects (null for any other claim). The amount may now be below 0, so the column
-- is rebuilt without its old 0-or-more check.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(12, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD COLUMN corrects BIGINT;
-- The signed-in user who opened a claim; null for a claim never opened. That user cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
-- The sheet's terms: the number of days after a claim's date that it is due by.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one record for a change to a sheet: the event, then sheet=&lt;id&gt; and by=&lt;user&gt;, then
     * the fields, separated by single spaces. Inside a transaction the record is written only once
     * it commits, so a change that is refused or rolled back writes nothing.
     */
    public void change(String event, String sheetId, String user, String... fields) {
        StringBuilder entry = new StringBuilder(event).append(" sheet=").append(sheetId).append(" by=").append(user);
        for (String field : fields) {
            entry.append(' ').append(field);
        }
        String line = entry.toString();
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    record(line);
                }
            });
        } else {
            record(line);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.Resource;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.resource.PathResourceResolver;

/**
 * Serve the SPA from static/ with a deep-link fallback: an unknown, non-API path returns
 * index.html so a browser refresh on a client route works. OfficeFloor REST routes and Spring
 * endpoints are matched first; only unmatched, non-{@code api/} paths fall through to the SPA.
 * TODO: confirm the API path prefix used by the OfficeFloor routes ("api/" assumed here).
 */
@Configuration
public class SpaConfig implements WebMvcConfigurer {

    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        registry.addResourceHandler("/**")
                .addResourceLocations("classpath:/static/")
                .resourceChain(true)
                .addResolver(new PathResourceResolver() {
                    @Override
                    protected Resource getResource(String resourcePath, Resource location) throws IOException {
                        if (resourcePath.startsWith("api/")) {
                            return null; // let the API handle / 404 it
                        }
                        Resource requested = location.createRelative(resourcePath);
                        return (requested.exists() && requested.isReadable())
                                ? requested
                                : location.createRelative("index.html");
                    }
                });
    }
}
