140	              <td><app-person-claims [personId]="p.id" [personName]="p.name" [grades]="p.grades" [retiredFrom]="p.retiredFrom" /></td>
141	              <td>
142	                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="edit(p)">
143	                  Edit<span class="visually-hidden"> {{ p.name }}</span>
144	                </button>
145	                <button type="button" data-testid="person-hold-toggle" (click)="toggleHold(p)">
146	                  {{ p.held ? 'Release' : 'Hold' }}<span class="visually-hidden"> {{ p.name }}</span>
147	                </button>
148	                <label [for]="'person-patron-select-' + p.id">Patron</label>
149	                <select
150	                  [id]="'person-patron-select-' + p.id"
151	                  data-testid="person-patron-select"
152	                  (change)="setPatronChoice(p.id, $any($event.target).value)"
153	                >
154	                  <option value="" [selected]="patronChoice(p.id) === ''">Choose a person</option>
155	                  @for (o of people(); track o.id) {
156	                    <option [value]="o.id" [selected]="patronChoice(p.id) === '' + o.id">{{ o.name }}</option>
157	                  }
158	                </select>
159	                <button type="button" data-testid="person-patron-add" (click)="addPatron(p)">
160	                  Add patron<span class="visually-hidden"> for {{ p.name }}</span>
161	                </button>
162	                @if (patronError()?.id === p.id) {
163	                  <p role="alert" data-testid="person-patron-error">{{ patronError()?.message }}</p>
164	                }
165	                @if (p.retiredFrom === null) {
166	                  <label [for]="'person-retire-date-' + p.id">Retire from</label>
167	                  <input
168	                    [id]="'person-retire-date-' + p.id"
169	                    type="date"
170	                    data-testid="person-retire-date"
171	                    [value]="retireDate(p.id)"
172	                    (input)="setRetireDate(p.id, $any($event.target).value)"
173	                  />
174	                  <button type="button" data-testid="person-retire" (click)="retire(p)">
175	                    Retire<span class="visually-hidden"> {{ p.name }}</span>
176	                  </button>
177	                }
178	                @if (rowError()?.id === p.id) {
179	                  <p role="alert" data-testid="person-error">{{ rowError()?.message }}</p>
180	                }
181	              </td>
182	            </tr>
183	          }
184	        </tbody>
185	      </table>
186	
187	      <p>Claimed total <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
188	      <p>Due total <strong data-testid="rollup-due-total">{{ dueTotalAll() }}</strong></p>
189	      <p>Overdue <strong data-testid="rollup-overdue-count">{{ overdueAll().count }}</strong></p>
190	      <p>Overdue total <strong data-testid="rollup-overdue-total">{{ formatCents(overdueAll().cents) }}</strong></p>
191	
192	      <app-periods [people]="people()" />
193	    </section>
194	  `,
195	})
196	export class People {
197	  protected readonly api = inject(PeopleApi);
198	  private readonly session = inject(Session);
199	  private readonly claims = inject(Claims);
200	  private readonly rates = inject(Rates);
201	  private readonly periods = inject(Periods);
202	
203	  protected readonly grades = GRADES;
204	  protected readonly formatCents = formatCents;
205	  protected readonly people = signal<Person[]>([]);
206	  protected readonly name = signal('');
207	  protected readonly grade = signal<Grade>('A');
208	  /** The date the form's grade applies from; the sheet's today until another is typed. */
209	  protected readonly gradeFrom = linkedSignal(() => this.session.today() ?? '');
210	  protected readonly editingId = signal<number | null>(null);
211	  /** The version of the person the editor loaded. */
212	  private editingVersion = 0;
213	  /** Set while a submit awaits the store, so a second submit does not store a second record. */
214	  private saving = false;
215	  protected readonly error = signal<string | null>(null);
216	  protected readonly importText = signal('');
217	  protected readonly importResult = signal<ImportResult | null>(null);
218	  protected readonly importError = signal<string | null>(null);
219	  /** Set while an import awaits the store, so a second submit does not import twice. */
220	  private importing = false;
221	  protected readonly quickName = signal('');
222	  protected readonly quickAmount = signal('');
223	  protected readonly quickError = signal<string | null>(null);
224	  /** Set while a quick add awaits the store, so a second submit does not store a second claim. */
225	  private quickAdding = false;
226	  /** The retire date typed on each person's row, by person id; the sheet's today when not typed. */
227	  private readonly retireDates = signal<ReadonlyMap<number, string>>(new Map());
228	  /** The patron chosen on each person's row, by person id, as the chosen person's id. */
229	  private readonly patronChoices = signal<ReadonlyMap<number, string>>(new Map());
230	  /** The error of the last patron added on a person's row, if it was refused. */
231	  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
232	  /** The error of the last action taken on a person's row, if it was refused. */
233	  protected readonly rowError = signal<{ id: number; message: string } | null>(null);
234	
235	  /** The ids of the people with a draft claim. */
236	  private readonly withDrafts = computed(
237	    () => new Set(this.claims.all().filter((c) => c.status === 'DRAFT').map((c) => c.personId)),
238	  );
239	  /**
240	   * The people with a draft claim, kept a moment after their last draft is opened or voided, so the
241	   * result of that action is seen before a retired person leaves the list.
242	   */
243	  private readonly keptListed = signal<ReadonlySet<number>>(new Set());
244	
245	  /**
246	   * The people listed: retired people are left out unless "show retired" is on, except while they
247	   * still have a draft claim, so it can be opened or voided.
248	   */
249	  protected readonly listed = computed(() => {
250	    const kept = this.keptListed();
251	    return this.people().filter((p) => p.retiredFrom === null || this.api.showRetired() || kept.has(p.id));
252	  });
253	
254	  /** Each person's claimed in cents, by person id: the amounts of their counted claims. */
255	  private readonly claimedCents = computed(() => {
256	    const byId = new Map(this.people().map((p) => [p.id, p]));
257	    const out = new Map<number, number>();
258	    for (const c of this.claims.all()) {
259	      const person = byId.get(c.personId);
260	      if (person !== undefined && counts(c, person)) out.set(c.personId, (out.get(c.personId) ?? 0) + toCents(c.amount));
261	    }
262	    return out;
263	  });
264	
265	  protected readonly claimedTotal = computed(() =>
266	    formatCents([...this.claimedCents().values()].reduce((sum, c) => sum + c, 0)),
267	  );
268	
269	  /**
270	   * Each person's due-total in cents, by person id: the sum of their counted claims' due figures as
271	   * shown (each already rounded), skipping those that are n/a; 0 when none has a figure.
272	   */
273	  private readonly dueCents = computed(() => {
274	    const out = new Map<number, number>();
275	    for (const p of this.people()) {
276	      const figures = this.claims
277	        .all()
278	        .filter((c) => c.personId === p.id && counts(c, p))
279	        .map((c) => this.rates.dueOf(c, gradeOn(p.grades, c.date)))
280	        .filter((c) => c !== undefined);
281	      out.set(p.id, figures.reduce((sum, c) => sum + c, 0));
282	    }
283	    return out;
284	  });
285	
286	  /** Everyone's due-total added up, skipping those that are n/a. */
287	  protected readonly dueTotalAll = computed(() =>
288	    formatCents([...this.dueCents().values()].reduce((sum, c) => sum + c, 0)),
289	  );
290	
291	  /**
292	   * Each person's overdue claims that count, by person id: how many, and their due figures added up
293	   * in cents, skipping those that are n/a.
294	   */
295	  private readonly overdueByPerson = computed(() => {
296	    const terms = this.session.terms() ?? 14;
297	    const today = this.session.today() ?? '';
298	    const out = new Map<number, { count: number; cents: number }>();
299	    for (const p of this.people()) {
300	      const late = this.claims.all().filter((c) => c.personId === p.id && counts(c, p) && overdue(c, terms, today));
301	      out.set(p.id, {
302	        count: late.length,
303	        cents: late.map((c) => this.rates.dueOf(c, gradeOn(p.grades, c.date)) ?? 0).reduce((sum, c) => sum + c, 0),
304	      });
305	    }
306	    return out;
307	  });
308	
309	  /** Everyone's overdue claims that count: how many, and their due-total in cents. */
310	  protected readonly overdueAll = computed(() =>
311	    [...this.overdueByPerson().values()].reduce(
312	      (all, o) => ({ count: all.count + o.count, cents: all.cents + o.cents }),
313	      { count: 0, cents: 0 },
314	    ),
315	  );
316	
317	  constructor() {
318	    effect((onCleanup) => {
319	      const drafts = this.withDrafts();
320	      this.keptListed.update((kept) => new Set([...kept, ...drafts]));
321	      const timer = setTimeout(() => this.keptListed.set(this.withDrafts()), LEAVE_DELAY_MS);
322	      onCleanup(() => clearTimeout(timer));
323	    });
324	    // Re-read the store each time the sheet is (re-)loaded.
325	    effect(() => {
326	      this.session.loads();
327	      untracked(() => {
328	        this.reset();
329	        this.importText.set('');
330	        this.importResult.set(null);
331	        this.importError.set(null);
332	        this.quickName.set('');
333	        this.quickAmount.set('');
334	        this.quickError.set(null);
335	        this.retireDates.set(new Map());
336	        this.rowError.set(null);
337	        this.patronChoices.set(new Map());
338	        this.patronError.set(null);
339	        void this.session.track(this.reload());
340	        void this.session.track(this.claims.reload());
341	      });
342	    });
343	  }
344	
345	  protected claimed(personId: number): string {
346	    return formatCents(this.claimedCents().get(personId) ?? 0);
347	  }
348	
349	  /** The person's grade in force on the sheet's today. */
350	  protected gradeToday(person: Person): Grade {
351	    return gradeOn(person.grades, this.session.today() ?? '');
352	  }
353	
354	  protected dueTotal(person: Person): string {
355	    const cents = this.dueCents().get(person.id);
356	    return cents === undefined ? 'n/a' : formatCents(cents);
357	  }
358	
359	  /** The names of the person's patrons, sorted, comma and space separated. */
360	  protected patronNames(person: Person): string {
361	    const byId = new Map(this.people().map((p) => [p.id, p.name]));
362	    return person.patronIds
363	      .map((id) => byId.get(id))
364	      .filter((n) => n !== undefined)
365	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
366	      .join(', ');
367	  }
368	
369	  /** The person's patrons' due-totals added up, skipping those that are n/a; 0.00 with no patrons. */
370	  protected backing(person: Person): string {
371	    const due = this.dueCents();
372	    return formatCents(person.patronIds.reduce((sum, id) => sum + (due.get(id) ?? 0), 0));
373	  }
374	
375	  protected patronChoice(personId: number): string {
376	    return this.patronChoices().get(personId) ?? '';
377	  }
378	
379	  protected setPatronChoice(personId: number, value: string): void {
380	    this.patronChoices.update((choices) => new Map(choices).set(personId, value));
381	    if (this.patronError()?.id === personId) this.patronError.set(null);
382	  }
383	
384	  /** Name the person chosen on the row as one of this person's patrons. */
385	  protected async addPatron(person: Person): Promise<void> {
386	    this.patronError.set(null);
387	    this.rowError.set(null);
388	    const patronId = Number(this.patronChoice(person.id));
389	    if (!patronId) {
390	      this.patronError.set({ id: person.id, message: 'Choose a person to name as a patron.' });
391	      return;
392	    }
393	    if (patronId === person.id) {
394	      this.patronError.set({ id: person.id, message: 'A person cannot be their own patron.' });
395	      return;
396	    }
397	    if (person.patronIds.includes(patronId)) {
398	      this.patronError.set({ id: person.id, message: 'That person is already a patron.' });
399	      return;
400	    }
401	    try {
402	      const saved = await this.api.addPatron(person.id, patronId);
403	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
404	      this.patronChoices.update((choices) => new Map(choices).set(person.id, ''));
405	    } catch (e) {
406	      this.patronError.set({
407	        id: person.id,
408	        message: e instanceof HttpErrorResponse && e.status === 409
409	          ? 'That person is already a patron.'
410	          : e instanceof HttpErrorResponse && e.status === 422
411	          ? 'A person cannot be their own patron.'
412	          : 'The patron could not be added.',
413	      });
414	    }
415	  }
416	
417	  protected overdueOf(personId: number): { count: number; cents: number } {
418	    return this.overdueByPerson().get(personId) ?? { count: 0, cents: 0 };
419	  }
420	
421	  protected retireDate(personId: number): string {
422	    return this.retireDates().get(personId) ?? this.session.today() ?? '';
423	  }
424	
425	  protected setRetireDate(personId: number, date: string): void {
426	    this.retireDates.update((dates) => new Map(dates).set(personId, date));
427	    if (this.rowError()?.id === personId) this.rowError.set(null);
428	  }
429	
430	  /** Retire the person from the date on their row (the sheet's today when left as it is). */
431	  protected async retire(person: Person): Promise<void> {
432	    this.rowError.set(null);
433	    this.patronError.set(null);
434	    const from = this.retireDate(person.id).trim();
435	    if (!/^\d{4}-\d{2}-\d{2}$/.test(from)) {
436	      this.rowError.set({ id: person.id, message: 'Enter a date as yyyy-mm-dd.' });
437	      return;
438	    }
439	    try {
440	      const saved = await this.api.retire(person.id, from);
441	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
442	    } catch (e) {
443	      this.rowError.set({
444	        id: person.id,
445	        message: e instanceof HttpErrorResponse && e.status === 409
446	          ? 'This person is already retired.'
447	          : 'The person could not be retired.',
448	      });
449	    }
450	  }
451	
452	  /** Put the person on hold, or release them when they are held. */
453	  protected async toggleHold(person: Person): Promise<void> {
454	    this.rowError.set(null);
455	    this.patronError.set(null);
456	    try {
457	      const saved = await this.api.setHeld(person.id, !person.held);
458	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
459	    } catch (e) {
460	      this.rowError.set({
461	        id: person.id,
462	        message: e instanceof HttpErrorResponse && e.status === 409
463	          ? (person.held ? 'This person is not on hold.' : 'This person is already on hold.')
464	          : (person.held ? 'The person could not be released.' : 'The person could not be put on hold.'),
465	      });
466	    }
467	  }
468	
469	  protected edit(person: Person): void {
470	    this.editingId.set(person.id);
471	    this.editingVersion = person.version;
472	    this.name.set(person.name);
473	    this.grade.set(this.gradeToday(person));
474	    this.gradeFrom.set(this.session.today() ?? '');
475	    this.error.set(null);
476	  }
477	
478	  protected reset(): void {
479	    this.editingId.set(null);
480	    this.name.set('');
481	    this.grade.set('A');
482	    this.gradeFrom.set(this.session.today() ?? '');
483	    this.error.set(null);
484	  }
485	
486	  protected async save(event: Event): Promise<void> {
487	    event.preventDefault();
488	    if (this.saving) return;
489	    this.error.set(null);
490	    const fields = { name: this.name(), grade: this.grade() };
491	    if (!fields.name.trim()) {
492	      this.error.set('Enter a name.');
493	      return;
494	    }
495	    const gradeFrom = this.gradeFrom().trim();
496	    if (gradeFrom && !/^\d{4}-\d{2}-\d{2}$/.test(gradeFrom)) {
497	      this.error.set('Enter the grade\'s from-date as yyyy-mm-dd.');
498	      return;
499	    }
500	    const id = this.editingId();
501	    this.saving = true;
502	    try {
503	      if (id === null) {
504	        const added = await this.api.add(fields);
505	        this.people.update((list) => [...list, added]);
506	      } else {
507	        const saved = await this.api.update(id, this.editingVersion, { ...fields, gradeFrom });
508	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
509	      }
510	      this.reset();
511	    } catch (e) {
512	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
513	        await this.showCurrent(id);
514	        this.error.set('Someone else saved this person since you opened it. Their values are shown; open it again to edit.');
515	        return;
516	      }
517	      if (e instanceof HttpErrorResponse && e.status === 409) {
518	        this.error.set('That name is already in use on this sheet.');
519	        return;
520	      }
521	      this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
522	    } finally {
523	      this.saving = false;
524	    }
525	  }
526	
527	  protected async importPeople(event: Event): Promise<void> {
528	    event.preventDefault();
529	    if (this.importing) return;
530	    this.importResult.set(null);
531	    this.importError.set(null);
532	    this.importing = true;
533	    try {
534	      const result = await this.api.importLines(this.importText());
535	      this.importResult.set(result);
536	      if (result.added > 0 || result.updated > 0) {
537	        this.importText.set('');
538	        await this.reload();
539	      }
540	    } catch {
541	      this.importError.set('The people could not be imported.');
542	    } finally {
543	      this.importing = false;
544	    }
545	  }
546	
547	  /**
548	   * Add a DRAFT claim dated the sheet's today for the named person, adding the person (grade A)
549	   * first when the name is not on the sheet; the rules of the person and claim forms apply.
550	   */
551	  protected async quickAdd(event: Event): Promise<void> {
552	    event.preventDefault();
553	    if (this.quickAdding) return;
554	    this.quickError.set(null);
555	    const name = this.quickName().trim();
556	    const amount = this.quickAmount().trim();
557	    if (!name) {
558	      this.quickError.set('Enter a name.');
559	      return;
560	    }
561	    if (name.length > 100) {
562	      this.quickError.set('The name is too long.');
563	      return;
564	    }
565	    if (!AMOUNT.test(amount)) {
566	      this.quickError.set('Enter an amount of 0.00 or more, with at most two decimals.');
567	      return;
568	    }
569	    if (this.periods.closedOn(this.session.today() ?? '')) {
570	      this.quickError.set('Today is in a closed period, so no claim can be added.');
571	      return;
572	    }
573	    this.quickAdding = true;
574	    try {
575	      const added = await this.claims.quickAdd(name, amount);
576	      if (!this.people().some((p) => p.id === added.personId)) await this.reload();
577	      this.quickName.set('');
578	      this.quickAmount.set('');
579	    } catch (e) {
580	      this.quickError.set(e instanceof HttpErrorResponse && e.status === 423
581	        ? 'Today is in a closed period, so no claim can be added.'
582	        : e instanceof HttpErrorResponse && e.status === 422
583	        ? 'That person is retired before today, so no claim can be added.'
584	        : 'The claim could not be added.');
585	    } finally {
586	      this.quickAdding = false;
587	    }
588	  }
589	
590	  /** Re-read the store and show the person's current values in the form and in their row. */
591	  private async showCurrent(id: number): Promise<void> {
592	    await this.reload();
593	    const current = this.people().find((p) => p.id === id);
594	    if (current) {
595	      this.name.set(current.name);
596	      this.grade.set(this.gradeToday(current));
597	    }
598	  }
599	
600	  private async reload(): Promise<void> {
601	    try {
602	      this.people.set(await this.api.list());
603	    } catch {
604	      this.people.set([]);
605	    }
606	  }
607	}
