1	import { Component, computed, effect, inject, input, signal, untracked } from '@angular/core';
2	import { Claims, counts, formatCents } from '../../core/claims';
3	import { Person, gradeOn } from '../../core/people';
4	import { PERIOD_NAME, Period, Periods } from '../../core/periods';
5	import { Rates } from '../../core/rates';
6	import { Session } from '../../core/session';
7	
8	// The sheet's periods, each with the due-total of the counted claims dated in it, and the form that adds one.
9	@Component({
10	  selector: 'app-periods',
11	  template: `
12	    <section aria-labelledby="periods-heading">
13	      <h2 id="periods-heading">Periods</h2>
14	
15	      <form (submit)="save($event)">
16	        <label for="period-name">Name</label>
17	        <input
18	          id="period-name"
19	          data-testid="period-form-name"
20	          [value]="name()"
21	          (input)="name.set($any($event.target).value); error.set(null)"
22	        />
23	        <label for="period-from">From</label>
24	        <input
25	          id="period-from"
26	          type="date"
27	          data-testid="period-form-from"
28	          [value]="from()"
29	          (input)="from.set($any($event.target).value); error.set(null)"
30	        />
31	        <label for="period-to">To</label>
32	        <input
33	          id="period-to"
34	          type="date"
35	          data-testid="period-form-to"
36	          [value]="to()"
37	          (input)="to.set($any($event.target).value); error.set(null)"
38	        />
39	        <button type="submit" data-testid="period-form-submit">Add period</button>
40	        @if (error(); as err) {
41	          <p role="alert" data-testid="period-form-error">{{ err }}</p>
42	        }
43	      </form>
44	
45	      <table>
46	        <thead>
47	          <tr><th scope="col">Name</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Due</th><th scope="col">Closed</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
48	        </thead>
49	        <tbody>
50	          @for (p of periods.all(); track p.id) {
51	            <tr [attr.data-testid]="'period-row-' + p.name">
52	              <td data-testid="period-name">{{ p.name }}</td>
53	              <td data-testid="period-from">{{ p.from }}</td>
